window.AUTH=window.AUTH||{};window.AUTH["22-58"]={"d":"22-58","id":"2022/22-58","n":"United States v. Texas","briefs":[{"k":"petitioner","label":"Brief of petitioners United States, et al.","date":"2022-09-12","url":"https://www.supremecourt.gov/DocketPDF/22/22-58/237711/20220912201922622_22-58tsUnitedStates.pdf","side":"pet","n":98},{"k":"respondent","label":"Brief of respondents Texas, et al.","date":"2022-10-18","url":"https://www.supremecourt.gov/DocketPDF/22/22-58/243365/20221018140615698_US%20v.%20Texas%20-%20Brief%20for%20Respondents.pdf","side":"res","n":108},{"k":"reply","label":"Reply of petitioners United States, et al.","date":"2022-11-17","url":"https://www.supremecourt.gov/DocketPDF/22/22-58/246874/20221117181036700_22-58rbUnitedStates.pdf","side":"pet","n":60}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/599us1r47_8m58.pdf","tr":true,"items":[{"t":"case","label":"Aberdeen & Rockfish R.R. v. Students Challenging Regulatory Agency Procedures (SCRAP)","cite":"422 U.S. 289","y":1975,"id":"1974/73-1966","sc":1,"sum":"In December 1971, the Nation's railroads, citing sharply increasing costs and decreasing or negative profits, collectively proposed to file tariffs increasing their freight rates by a temporary surcharge across the board. The Interstate Commerce Commission (ICC), in the ensuing general revenue proceeding, finding that the railroads had a critical and immediate need for revenue, declined to exercise its power to …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46","1":"46","2":"21"}},{"t":"case","label":"Alfred L. Snapp & Son, Inc. v. Puerto Rico ex rel. Barez","cite":"458 U.S. 592","y":1982,"id":"1981/80-1305","sc":1,"sum":"Puerto Rico has parens patriae standing to maintain this suit. Pp. 600-610. ALFRED L. SNAPP & SON, INC. v. PUERTO RICO (a) In order to maintain a parens patriaeaction, a State must articulate an interest apart from the interests of particular private parties, that is, the State must be more than a nominal party. The State must express a \"quasi-sovereign\" interest, such as its interest in the health and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12, 23","1":"17, 23","2":"7"}},{"t":"case","label":"American Hosp. Ass’n v. Bowen","cite":"834 F.2d 1037","y":1987,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/834/1037/","by":{"0":"38"}},{"t":"case","label":"Arizona v. United States","cite":"567 U.S. 387","y":2012,"id":"2011/11-182","sc":1,"op":3,"sum":"The Court found that Arizona's state immigration provisions conflicted in part with federal immigration laws.","sumSrc":"Oyez","by":{"0":"2","1":"17"}},{"t":"case","label":"Barton v. Barr","cite":"140 S. Ct. 1442","y":2020,"id":"2019/18-725","sc":1,"sum":"The Court held that in determining eligibility for cancellation of removal of a lawful permanent resident who commits a serious crime, an offense listed in 8 U.S.C. § 1182(a)(2) committed during the initial seven years of residence need not be one of the offenses of removal.","sumSrc":"Oyez","by":{"0":"2"}},{"t":"case","label":"Biden v. Texas","cite":"142 S. Ct. 2528","y":2022,"id":"2021/21-954","sc":1,"sum":"The Government’s rescission of Migrant Protection Protocols did not violate section 1225 of the Immigration and Nationality Act, and the then-Secretary of Homeland Security’s October 29 Memoranda constituted valid final agency action.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"48","1":"44, 47","2":"23"}},{"t":"case","label":"California v. Texas","cite":"141 S. Ct. 2104","y":2021,"id":"2020/19-840","sc":1,"sum":"Plaintiffs lack standing to challenge the Patient Protection and Affordable Care Act’s minimum essential coverage provision.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"24, 43","1":"19"}},{"t":"case","label":"Chrysler Corp. v. Brown","cite":"441 U.S. 281","y":1979,"id":"1978/77-922","sc":1,"sum":"Petitioner, as a party to numerous Government contracts, was required to comply with Executive Orders 11246 and 11375, which charge the Secretary of Labor with ensuring that corporations that benefit from Government contracts provide equal employment opportunity regardless of race or sex. Regulations promulgated by the Department of Labor's Office of Federal Contract Compliance Programs (OFCCP) require Government …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37"}},{"t":"case","label":"City of Chicago v. Morales","cite":"527 U.S. 41","y":1999,"id":"1998/97-1121","sc":1,"sum":"The Court held that Chicago's Gang Congregation Ordinance was unconstitutionally vague and provided law enforcement officials too much discretion to decide what activities constitute loitering.","sumSrc":"Oyez","by":{"0":"28","1":"30"}},{"t":"case","label":"DHS v. New York","cite":"140 S. Ct. 599","y":2020,"url":"https://www.courtlistener.com/c/S.%20Ct./140/599/","sc":1,"by":{"0":"44"}},{"t":"case","label":"DHS v. Regents of the Univ. of Cal.","cite":"140 S. Ct. 1891","y":2020,"id":"2019/18-587","sc":1,"op":2,"ar":1,"sum":"The Court held that the Department of Homeland Security’s decision to rescind the Deferred Action for Childhood Arrivals program was arbitrary and capricious under the Administrative Procedure Act.","sumSrc":"Oyez","by":{"0":"36, 46","1":"passim","2":"4, 15"}},{"t":"case","label":"DaimlerChrysler Corp. v. Cuno","cite":"547 U.S. 332","y":2006,"id":"2005/04-1704","sc":1,"sum":"The Supreme Court did not reach the central question presented, finding instead that Cuno and the other plaintiffs did not have standing to bring the suit. Chief Justice John Roberts, for the unanimous Court, wrote that simply alleging standing based on their status as taxpayers in Ohio and Michigan did not give them a sufficiently strong interest in the case.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Demore v. Kim","cite":"538 U.S. 510","y":2003,"id":"2002/01-1491","sc":1,"op":2,"sum":"The Court held, 6-3, that the Immigration and Nationality Act does not deprive the federal courts of jurisdiction to grant habeas relief to aliens challenging their detention under section 1226(c) and, 5-4, that detention during removal proceedings is a constitutionally permissible part of that process.","sumSrc":"Oyez","by":{"0":"24, 26","1":"passim","2":"7, 11"}},{"t":"case","label":"Department of Commerce v. New York","cite":"139 S. Ct. 2551","y":2019,"id":"2018/18-966","sc":1,"op":3,"ar":2,"sum":"The Secretary did not violate the Enumeration Clause or the Census Act in deciding to reinstate a citizenship question on the 2020 census questionnaire, but the District Court was warranted in remanding the case back to the agency where the evidence tells a story that does not match the Secretary’s explanation for his decision.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"11, 24, 36","1":"18, 19","2":"4"}},{"t":"case","label":"Direct Mktg. Ass’n v. Brohl","cite":"575 U.S. 1","y":2015,"id":"2014/13-1032","sc":1,"sum":"The Court held that the Tax Injunction Act does not prevent federal court review of state tax laws, unless such review could restrict the ability of the state to assess or collect its own taxes.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"FCC v. Prometheus Radio Project","cite":"141 S. Ct. 1150","y":2021,"id":"2020/19-1231","sc":1,"sum":"The Federal Communications Commission’s 2017 decision to repeal or modify three of its media ownership rules was not arbitrary or capricious for purposes of the Administrative Procedure Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"33, 35","1":"34, 35","2":"14"}},{"t":"case","label":"FEC v. Akins","cite":"524 U.S. 11","y":1998,"id":"1997/96-1590","sc":1,"op":2,"ar":1,"sum":"The Court held that voters seeking information, to which they believe FECA entitles them, have standing to challenge the FEC's decision not to bring an enforcement action. Because FECA seeks to address the voters' injury, the failure to obtain relevant information, Justice Breyer concluded that the voters had prudential standing.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Florida v. Mellon","cite":"273 U.S. 12","y":1927,"id":"scdb/1926-132","sc":1,"op":4,"ar":1,"sum":"Rule to show cause argued November 23, 1926.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"7, 12, 13, 23","1":"19, 20, 23"}},{"t":"case","label":"Fulton v. City of Philadelphia","cite":"141 S. Ct. 1868","y":2021,"id":"2020/19-123","sc":1,"sum":"Philadelphia’s refusal to contract with Catholic Social Services for the provision of foster care services unless CSS agrees to certify same-sex couples as foster parents violates the Free Exercise Clause of the First Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"47"}},{"t":"case","label":"Garland v. Aleman Gonzalez","cite":"142 S. Ct. 2057","y":2022,"id":"2021/20-322","sc":1,"sum":"Title 8 U. S. C. §1252(f)(1)—which generally strips lower courts of “jurisdiction or authority” to “enjoin or restrain the operation of ” certain provisions of the Immigration and Nationality Act—deprived the District Courts of jurisdiction in these cases to entertain respondents’ requests for class-wide injunctive relief.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"10, 44, 45, 46, 47","1":"46","2":"20, 21"}},{"t":"case","label":"Hecht Co. v. Bowles","cite":"321 U.S. 321","y":1944,"id":"scdb/1943-092","sc":1,"sum":"1. Under § 205 (a) of the Emergency Price Control Act of 1942, the grant of an injunction, upon application of the Administrator and a showing that the defendant has engaged in acts or practices violative of § 4 of the Act, is not mandatory but is in the discretion of the court.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43"}},{"t":"case","label":"Heckler v. Chaney","cite":"470 U.S. 821","y":1985,"id":"1984/83-1878","sc":1,"op":17,"ar":3,"sum":"Recognizing the “general unsuitability for judicial review of agency decisions to refuse enforcement”.","sumSrc":"opinion","by":{"0":"18, 28","1":"1, 30","2":"13"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"138 S. Ct. 830","y":2018,"id":"2017/15-1204","sc":1,"sum":"The Court held that non-citizens who are subject to mandatory detention under the Immigration and Nationality Act are not entitled to periodic bond hearings. with the possibility of release if they are detained for longer than six months.","sumSrc":"Oyez","by":{"0":"26","1":"5, 24, 26, 44"}},{"t":"case","label":"Johnson v. Guzman Chavez","cite":"141 S. Ct. 2271","y":2021,"id":"2020/19-897","sc":1,"sum":"The detention of an alien ordered removed from the United States who reenters without authorization is governed by 8 U. S. C. §1231.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"4, 30","1":"2, 5, 26"}},{"t":"case","label":"Laird v. Tatum","cite":"408 U.S. 1","y":1972,"id":"1971/71-288","sc":1,"sum":"Respondents' claim that their First Amendment rights are chilled, due to the mere existence of this data-gathering system, does not constitute a justiciable controversy on the basis of the record in this case, disclosing as it does no showing of objective harm or threat of specific future harm. Pp. 3-16. 144 U. S. App. D. C. 72, 444 F. 2d 947, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Lincoln v. Vigil","cite":"508 U.S. 182","y":1993,"id":"1992/91-1833","sc":1,"op":2,"sum":"The Indian Health Service receives yearly lump-sum appropriations from Congress, and expends the funds under authority of the Snyder Act and the Indian Health Care Improvement Act to provide health care for American Indian and Alaska Native people. Out of these appropriations the Service funded, from 1978 to 1985, the Indian Children's Program (Program), which provided clinical services to handicapped Indian …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"36","2":"15"}},{"t":"case","label":"Linda R.S. v. Richard D.","cite":"410 U.S. 614","y":1973,"id":"1972/71-6078","sc":1,"op":23,"ar":3,"sum":"Although appellant has an interest in her child's support, application of Art. 602 would not result in support but only in the father's incarceration, and a private citizen lacks a judicially cognizable interest in the prosecution or nonprosecution of another. Pp. 616-619. 335 F. Supp. 804, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"7, 18, 19","1":"15","2":"6"}},{"t":"case","label":"Lujan v. Defenders of Wildlife","cite":"504 U.S. 555","y":1992,"id":"1991/90-1424","sc":1,"op":12,"sum":"Even if the Court were to assume that the agency-funded projects at issue threatened listed species, there was no proof that these actions would produce \"actual or imminent\" injuries to particular respondents who might some day wish to visit the foreign countries in question.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Mallinckrodt Chem. Works v. Missouri ex rel. Jones","cite":"238 U.S. 41","y":1915,"id":"scdb/1914-175","sc":1,"sum":"If it appears from the opinion of the trial court, that the question of equal protection, under the Fourteenth Amendment, was treated as sufficiently raised and specifically dealt with adversely to plaintiff in error, jurisdiction is conferred on this court under § 237, Judicial Code,","sumSrc":"Headnote (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"Massachusetts v. EPA","cite":"549 U.S. 497","y":2007,"id":"2006/05-1120","sc":1,"op":7,"sum":"The Court ruled that states could sue the EPA for potential damage to their territory caused by global warming, and that the Clean Air Act imposes a duty upon the EPA to regulate the emissions of carbon dioxide and other gases that contribute to global warming.","sumSrc":"Oyez","by":{"0":"23","1":"passim","2":"4, 5"}},{"t":"case","label":"Massachusetts v. Laird","cite":"400 U.S. 886","y":1970,"url":"https://supreme.justia.com/cases/federal/us/400/886/","sc":1,"op":1,"by":{"0":"16","1":"20"}},{"t":"case","label":"Massachusetts v. Mellon","cite":"262 U.S. 447","y":1923,"id":"1900-1940/262us447","sc":1,"op":2,"sum":"The Court held that the administration of federal statutes \"likely to produce addition taxation to be imposed upon a vast number of taxpayers\" was essentially a matter of public and not of individual concern.","sumSrc":"Oyez","by":{"0":"12, 23, 40","1":"23"}},{"t":"case","label":"Mendoza v. Perez","cite":"754 F.3d 1002","y":2014,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/754/1002/","by":{"0":"38","2":"16"}},{"t":"case","label":"Monsanto Co. v. Geertson Seed Farms","cite":"561 U.S. 139","y":2010,"id":"2009/09-475","sc":1,"ar":1,"sum":"The Court held that a district court must conduct an evidentiary hearing to enter an injunction.","sumSrc":"Oyez","by":{"0":"45","1":"42, 46"}},{"t":"case","label":"Motor Vehicle Mfrs. Ass’n of the U.S., Inc. v. State Farm Mut. Auto. Ins. Co.","cite":"463 U.S. 29","y":1983,"id":"1982/82-354","sc":1,"sum":"The Supreme Court held that the rescission of a standard should be reviewed based on whether the decision was arbitrary or capricious. Because the removal of a standard often entails the same level of policy changes as the promulgation of a law, it should be reviewed under the same tests.","sumSrc":"Oyez","by":{"0":"33, 34, 35","1":"34"}},{"t":"case","label":"Murphy v. NCAA","cite":"138 S. Ct. 1461","y":2018,"id":"2017/16-476","sc":1,"sum":"The Court decided that provisions of the Professional and Amateur Sports Protection Act (PASPA) that prohibit state authorization and licensing of sports gambling schemes violate the Constitution’s anticommandeering rule, and that no other PASPA provisions are severable from the provisions at issue.","sumSrc":"Oyez","by":{"0":"12","1":"18"}},{"t":"case","label":"National Mining Ass’n v. McCarthy","cite":"758 F.3d 243","y":2014,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/758/243/","by":{"0":"37, 38","1":"37","2":"16"}},{"t":"case","label":"Nielsen v. Preap","cite":"139 S. Ct. 954","y":2019,"id":"2018/16-1363","sc":1,"sum":"The Ninth Circuit’s judgments—that respondents, who are deportable for certain specified crimes, are not subject to 8 U. S. C. §1226(c)(2)’s mandatory-detention requirement because they were not arrested by immigration officials as soon as they were released from jail—are reversed, and the cases are remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"26, 48","1":"passim","2":"8, 9, 11"}},{"t":"case","label":"Patel v. Garland","cite":"142 S. Ct. 1614","y":2022,"id":"2021/20-979","sc":1,"sum":"Federal courts lack jurisdiction to review facts found as part of any judgment relating to the granting of discretionary-relief in immigration proceedings enumerated under 8 U. S. C. §1252(a)(2)(B)(i).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"25, 48","1":"27","2":"8"}},{"t":"case","label":"Printz v. United States","cite":"521 U.S. 898","y":1997,"id":"1996/95-1478","sc":1,"op":7,"sum":"The Court held that Congress could not require state agencies to perform federal duties under the Necessary and Proper Clause.","sumSrc":"Oyez","by":{"0":"12, 13"}},{"t":"case","label":"Raines v. Byrd","cite":"521 U.S. 811","y":1997,"id":"1996/96-1671","sc":1,"op":7,"ar":1,"sum":"In a 7-to-2 decision, which avoided the question of the Act's constitutionality, the Court held that the individual congressmen lacked proper Article III standing to maintain their suit. The Court explained that the congressmen failed to show how the allegedly unconstitutional Act resulted in their personal injury, since it applied to the entire institution of Congress.","sumSrc":"Oyez","by":{"0":"11, 15, 17","1":"15, 21, 22"}},{"t":"case","label":"Reno v. American-Arab Anti-Discrimination Comm.","cite":"525 U.S. 471","y":1999,"id":"1998/97-1252","sc":1,"op":2,"sum":"Announced by Justice Antonin Scalia, the Court ruled that the IIRIRA deprives federal courts of jurisdiction over the selective-enforcement claim.","sumSrc":"Oyez","by":{"0":"2, 28, 29, 32, 36","1":"30, 43, 48"}},{"t":"case","label":"Sampson v. Murray","cite":"415 U.S. 61","y":1974,"id":"1973/72-403","sc":1,"op":1,"sum":"Explaining that § 705 was “primarily intended to refect existing law”.","sumSrc":"opinion","by":{"0":"47","2":"17"}},{"t":"case","label":"Schlesinger v. Reservists Comm. to Stop the War","cite":"418 U.S. 208","y":1974,"id":"1973/72-1188","sc":1,"op":1,"sum":"Respondents-an association of present and former members of the Armed Forces Reserve opposing United States involvement in Vietnam, and five association members who were United States citizens and taxpayers-brought a class action on behalf, inter alia, of all United States citizens and taxpayers against petitioners, the Secretary of Defense and the three Service Secretaries, challenging the Reserve membership of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17","1":"20"}},{"t":"case","label":"South Carolina v. Katzenbach","cite":"383 U.S. 301","y":1966,"id":"1965/22_orig","sc":1,"op":1,"sum":"The Court held that the Fifteenth Amendment is a valid constitutional basis for the Voting Rights Act of 1965.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Stark v. Wickard","cite":"321 U.S. 288","y":1944,"id":"scdb/1943-091","sc":1,"sum":"that the producers had standing to sue. Pp. 289, 305.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Sure-Tan, Inc. v. NLRB","cite":"467 U.S. 883","y":1984,"id":"1983/82-945","sc":1,"op":4,"ar":1,"sum":"The Court held that that the NLRB can act to protect the labor rights of illegal immigrants because it serves the broader purpose of labor to have all workers represented, regardless of immigration status. Precedent establishes that the Board can protect the rights of any employee. The petitioners’ actions illegally discouraged union activity and caused the deportation of their employees.","sumSrc":"Oyez","by":{"0":"7, 18, 19","1":"15"}},{"t":"case","label":"Texas v. Biden","cite":"20 F.4th 928","y":2021,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/20/928/","op":1,"by":{"0":"40, 45"}},{"t":"case","label":"Town of Castle Rock v. Gonzales","cite":"545 U.S. 748","y":2005,"id":"2004/04-278","sc":1,"op":10,"ar":3,"sum":"The Court ruled that Gonzales had no constitutionally-protected property interest in the enforcement of the restraining order, and therefore could not claim that the police had violated her right to due process.","sumSrc":"Oyez","by":{"0":"8, 29, 30","1":"10, 30","2":"9, 11, 12, 13"}},{"t":"case","label":"TransUnion LLC v. Ramirez","cite":"141 S. Ct. 2190","y":2021,"id":"2020/20-297","sc":1,"op":7,"sum":"Only a plaintiff concretely harmed by a defendant’s violation of the Fair Credit Reporting Act has Article III standing to seek damages against that private defendant in federal court.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"10, 13, 19, 20","1":"23","2":"4, 6"}},{"t":"case","label":"Trump v. Hawaii","cite":"138 S. Ct. 2392","y":2019,"id":"2017/17-965","sc":1,"sum":"The Court held that President Donald Trump’s Proclamation restricting travel and immigration to the US from certain countries (“travel ban”) does not violate the president’s statutory authority or the Establishment Clause of the Constitution. The Court was also asked, but did not decide, whether a global injunction barring enforcement of parts of the Proclamation is impermissibly overbroad.","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"Trump v. New York","cite":"141 S. Ct. 530","y":2020,"id":"2020/20-366","sc":1,"sum":"Because plaintiffs have not shown standing and because the claims presented are not ripe for adjudication, the District Court’s judgment is vacated, and the case is remanded with instructions to dismiss for lack of jurisdiction.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"24"}},{"t":"case","label":"United States v. Richardson","cite":"418 U.S. 166","y":1974,"id":"1973/72-885","sc":1,"op":1,"sum":"The Court held that Richardson did not have standing to sue. Using the two-pronged standing test of Flast v. Cohen (1968), Chief Justice Burger found that there was no \"logical nexus between the status asserted [by Richardson as a taxpayer] and the claim sought to be adjudicated.\" It was clear to Burger that Richardson was not \"a proper and appropriate party to invoke federal judicial power\" on this issue.","sumSrc":"Oyez","by":{"0":"17"}},{"t":"case","label":"Vietnam Veterans of Am. v. Secretary of the Navy","cite":"843 F.2d 528","y":1988,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/843/528/","sum":"Observing that this exception “is quite independent of whether the procedures will be binding”.","sumSrc":"brief:0","by":{"0":"38"}},{"t":"case","label":"Wyoming v. Oklahoma","cite":"502 U.S. 437","y":1992,"id":"1991/112_orig","sc":1,"op":1,"sum":"Wyoming, a major coal-producing State, does not sell coal, but does impose a severance tax on those who extract it. From 1981 to 1986, Wyoming provided virtually 100% of the coal purchased by four Oklahoma electric utilities, including the Grand River Dam Authority (GRDA), a state agency. However, after the Oklahoma Legislature passed an Act requiring coal-fired electric utilities to burn a mixture containing at …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13","1":"20"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"0":"passim","2":"3, 5"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","stext":{"head":"§551. Definitions","paras":[[0,"For the purpose of this subchapter—"],[1,"(1) \"agency\" means each authority of the Government of the United States, whether or not it is within or subject to review by another agency, but does not include—"],[2,"(A) the Congress;"],[2,"(B) the courts of the United States;"],[2,"(C) the governments of the territories or possessions of the United States;"],[2,"(D) the government of the District of Columbia;"],[1,"or except as to the requirements of section 552 of this title—"],[2,"(E) agencies composed of representatives of the parties or of representatives of organizations of the parties to the disputes determined by them;"],[2,"(F) courts martial and military commissions;"],[2,"(G) military authority exercised in the field in time of war or in occupied territory; or"],[2,"(H) functions conferred by sections 1738, 1739, 1743, and 1744 of title 12; subchapter II of chapter 471 of title 49; or sections 1884, 1891–1902, and former section 1641(b)(2), of title 50, appendix; 1"],[1,"(2) \"person\" includes an individual, partnership, corporation, association, or public or private organization other than an agency;"],[1,"(3) \"party\" includes a person or agency named or admitted as a party, or properly seeking and entitled as of right to be admitted as a party, in an agency proceeding, and a person or agency admitted by an agency as a party for limited purposes;"],[1,"(4) \"rule\" means the whole or a part of an agency statement of general or particular applicability and future effect designed to implement, interpret, or prescribe law or policy or describing the organization, procedure, or practice requirements of an agency and includes the approval or prescription for the future of rates, wages, corporate or financial structures or reorganizations thereof, prices, facilities, appliances, services or allowances therefor or of valuations, costs, or accounting, or practices bearing on any of the foregoing;"],[1,"(5) \"rule making\" means agency process for formulating, amending, or repealing a rule;"],[1,"(6) \"order\" means the whole or a part of a final disposition, whether affirmative, negative, injunctive, or declaratory in form, of an agency in a matter other than rule making but including licensing;"],[1,"(7) \"adjudication\" means agency process for the formulation of an order;"],[1,"(8) \"license\" includes the whole or a part of an agency permit, certificate, approval, registration, charter, membership, statutory exemption or other form of permission;"],[1,"(9) \"licensing\" includes agency process respecting the grant, renewal, denial, revocation, suspension, annulment, withdrawal, limitation, amendment, modification, or conditioning of a license;"],[1,"(10) \"sanction\" includes the whole or a part of an agency—"],[2,"(A) prohibition, requirement, limitation, or other condition affecting the freedom of a person;"],[2,"(B) withholding of relief;"],[2,"(C) imposition of penalty or fine;"],[2,"(D) destruction, taking, seizure, or withholding of property;"],[2,"(E) assessment of damages, reimbursement, restitution, compensation, costs, charges, or fees;"],[2,"(F) requirement, revocation, or suspension of a license; or"],[2,"(G) taking other compulsory or restrictive action;"],[1,"(11) \"relief\" includes the whole or a part of an agency—"],[2,"(A) grant of money, assistance, license, authority, exemption, exception, privilege, or remedy;"],[2,"(B) recognition of a claim, right, immunity, privilege, exemption, or exception; or"],[2,"(C) taking of other action on the application or petition of, and beneficial to, a person;"],[1,"(12) \"agency proceeding\" means an agency process as defined by paragraphs (5), (7), and (9) of this section;"],[1,"(13) \"agency action\" includes the whole or a part of an agency rule, order, license, sanction, relief, or the equivalent or denial thereof, or failure to act; and"],[1,"(14) \"ex parte communication\" means an oral or written communication not on the public record with respect to which reasonable prior notice to all parties is not given, but it shall not include requests for status reports on any matter or proceeding covered by this subchapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/551?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§551. Definitions","tname":"Government Organization and Employees","by":{"0":"6","2":"2"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","stext":{"head":"§701. Application; definitions","paras":[[0,"(a) This chapter applies, according to the provisions thereof, except to the extent that—"],[1,"(1) statutes preclude judicial review; or"],[1,"(2) agency action is committed to agency discretion by law."],[0,"(b) For the purpose of this chapter—"],[1,"(1) \"agency\" means each authority of the Government of the United States, whether or not it is within or subject to review by another agency, but does not include—"],[2,"(A) the Congress;"],[2,"(B) the courts of the United States;"],[2,"(C) the governments of the territories or possessions of the United States;"],[2,"(D) the government of the District of Columbia;"],[2,"(E) agencies composed of representatives of the parties or of representatives of organizations of the parties to the disputes determined by them;"],[2,"(F) courts martial and military commissions;"],[2,"(G) military authority exercised in the field in time of war or in occupied territory; or"],[2,"(H) functions conferred by sections 1738, 1739, 1743, and 1744 of title 12; subchapter II of chapter 471 of title 49; or sections 1884, 1891–1902, and former section 1641(b)(2), of title 50, appendix; 1 and"],[1,"(2) \"person\", \"rule\", \"order\", \"license\", \"sanction\", \"relief\", and \"agency action\" have the meanings given them by section 551 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/701?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§701. Application; definitions","tname":"Government Organization and Employees","by":{"0":"6","2":"2"}},{"t":"usc","label":"5 U.S.C. § 553","url":"https://www.law.cornell.edu/uscode/text/5/553","subs":["(b)","(b)(A)"],"stext":{"head":"§553. Rule making","paras":[[0,"(a) This section applies, according to the provisions thereof, except to the extent that there is involved—"],[1,"(1) a military or foreign affairs function of the United States; or"],[1,"(2) a matter relating to agency management or personnel or to public property, loans, grants, benefits, or contracts."],[0,"(b) General notice of proposed rule making shall be published in the Federal Register, unless persons subject thereto are named and either personally served or otherwise have actual notice thereof in accordance with law. The notice shall include—"],[1,"(1) a statement of the time, place, and nature of public rule making proceedings;"],[1,"(2) reference to the legal authority under which the rule is proposed;"],[1,"(3) either the terms or substance of the proposed rule or a description of the subjects and issues involved; and"],[1,"(4) the Internet address of a summary of not more than 100 words in length of the proposed rule, in plain language, that shall be posted on the Internet website under section 206(d) of the E-Government Act of 2002 (44 U.S.C. 3501 note) (commonly known as regulations.gov)."],[0,"Except when notice or hearing is required by statute, this subsection does not apply—"],[1,"(A) to interpretative rules, general statements of policy, or rules of agency organization, procedure, or practice; or"],[1,"(B) when the agency for good cause finds (and incorporates the finding and a brief statement of reasons therefor in the rules issued) that notice and public procedure thereon are impracticable, unnecessary, or contrary to the public interest."],[0,"(c) After notice required by this section, the agency shall give interested persons an opportunity to participate in the rule making through submission of written data, views, or arguments with or without opportunity for oral presentation. After consideration of the relevant matter presented, the agency shall incorporate in the rules adopted a concise general statement of their basis and purpose. When rules are required by statute to be made on the record after opportunity for an agency hearing, sections 556 and 557 of this title apply instead of this subsection."],[0,"(d) The required publication or service of a substantive rule shall be made not less than 30 days before its effective date, except—"],[1,"(1) a substantive rule which grants or recognizes an exemption or relieves a restriction;"],[1,"(2) interpretative rules and statements of policy; or"],[1,"(3) as otherwise provided by the agency for good cause found and published with the rule."],[0,"(e) Each agency shall give an interested person the right to petition for the issuance, amendment, or repeal of a rule."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/553?type=usc&year=mostrecent&link-type=html"},"head":"§553. Rule making","tname":"Government Organization and Employees","by":{"0":"13, 13","2":"15"}},{"t":"usc","label":"5 U.S.C. § 703","url":"https://www.law.cornell.edu/uscode/text/5/703","stext":{"head":"§703. Form and venue of proceeding","paras":[[0,"The form of proceeding for judicial review is the special statutory review proceeding relevant to the subject matter in a court specified by statute or, in the absence or inadequacy thereof, any applicable form of legal action, including actions for declaratory judgments or writs of prohibitory or mandatory injunction or habeas corpus, in a court of competent jurisdiction. If no special statutory review proceeding is applicable, the action for judicial review may be brought against the United States, the agency by its official title, or the appropriate officer. Except to the extent that prior, adequate, and exclusive opportunity for judicial review is provided by law, agency action is subject to judicial review in civil or criminal proceedings for judicial enforcement."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/703?type=usc&year=mostrecent&link-type=html"},"op":6,"ar":2,"head":"§703. Form and venue of proceeding","tname":"Government Organization and Employees","by":{"0":"13","2":"2, 17, 18, 19"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(2)","(2)(A)","(1)"],"stext":{"head":"§706. Scope of review","paras":[[0,"To the extent necessary to decision and when presented, the reviewing court shall decide all relevant questions of law, interpret constitutional and statutory provisions, and determine the meaning or applicability of the terms of an agency action. The reviewing court shall—"],[1,"(1) compel agency action unlawfully withheld or unreasonably delayed; and"],[1,"(2) hold unlawful and set aside agency action, findings, and conclusions found to be—"],[2,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[2,"(B) contrary to constitutional right, power, privilege, or immunity;"],[2,"(C) in excess of statutory jurisdiction, authority, or limitations, or short of statutory right;"],[2,"(D) without observance of procedure required by law;"],[2,"(E) unsupported by substantial evidence in a case subject to sections 556 and 557 of this title or otherwise reviewed on the record of an agency hearing provided by statute; or"],[2,"(F) unwarranted by the facts to the extent that the facts are subject to trial de novo by the reviewing court."],[0,"In making the foregoing determinations, the court shall review the whole record or those parts of it cited by a party, and due account shall be taken of the rule of prejudicial error."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/706?type=usc&year=mostrecent&link-type=html"},"op":6,"ar":7,"head":"§706. Scope of review","tname":"Government Organization and Employees","by":{"0":"13, 13, 13","2":"17, 18, 19, 23, 18, 2, 16, 17, 18, 19, 20, 18"}},{"t":"usc","label":"42 U.S.C. § 7401","url":"https://www.law.cornell.edu/uscode/text/42/7401","stext":{"head":"§7401. Congressional findings and declaration of purpose","paras":[[0,"(a) Findings"],[0,"The Congress finds—"],[1,"(1) that the predominant part of the Nation's population is located in its rapidly expanding metropolitan and other urban areas, which generally cross the boundary lines of local jurisdictions and often extend into two or more States;"],[1,"(2) that the growth in the amount and complexity of air pollution brought about by urbanization, industrial development, and the increasing use of motor vehicles, has resulted in mounting dangers to the public health and welfare, including injury to agricultural crops and livestock, damage to and the deterioration of property, and hazards to air and ground transportation;"],[1,"(3) that air pollution prevention (that is, the reduction or elimination, through any measures, of the amount of pollutants produced or created at the source) and air pollution control at its source is the primary responsibility of States and local governments; and"],[1,"(4) that Federal financial assistance and leadership is essential for the development of cooperative Federal, State, regional, and local programs to prevent and control air pollution."],[0,"(b) Declaration"],[0,"The purposes of this subchapter are—"],[1,"(1) to protect and enhance the quality of the Nation's air resources so as to promote the public health and welfare and the productive capacity of its population;"],[1,"(2) to initiate and accelerate a national research and development program to achieve the prevention and control of air pollution;"],[1,"(3) to provide technical and financial assistance to State and local governments in connection with the development and execution of their air pollution prevention and control programs; and"],[1,"(4) to encourage and assist the development and operation of regional air pollution prevention and control programs."],[0,"(c) Pollution prevention"],[0,"A primary goal of this chapter is to encourage or otherwise promote reasonable Federal, State, and local governmental actions, consistent with the provisions of this chapter, for pollution prevention."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/7401?type=usc&year=mostrecent&link-type=html"},"head":"§7401. Congressional findings and declaration of purpose","tname":"The Public Health and Welfare","by":{"0":"23","2":"4"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(3)"],"stext":{"head":"§1101. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"administrator\" means the official designated by the Secretary of State pursuant to section 1104(b) of this title."],[0,"(2) The term \"advocates\" includes, but is not limited to, advises, recommends, furthers by overt act, and admits belief in."],[0,"(3) The term \"alien\" means any person not a citizen or national of the United States."],[0,"(4) The term \"application for admission\" has reference to the application for admission into the United States and not to the application for the issuance of an immigrant or nonimmigrant visa."],[0,"(5) The term \"Attorney General\" means the Attorney General of the United States."],[0,"(6) The term \"border crossing identification card\" means a document of identity bearing that designation issued to an alien who is lawfully admitted for permanent residence, or to an alien who is a resident in foreign contiguous territory, by a consular officer or an immigration officer for the purpose of crossing over the borders between the United States and foreign contiguous territory in accordance with such conditions for its issuance and use as may be prescribed by regulations. Such regulations shall provide that (A) each such document include a biometric identifier (such as the fingerprint or handprint of the alien) that is machine readable and (B) an alien presenting a border crossing identification card is not permitted to cross over the border into the United States unless the biometric identifier contained on the card matches the appropriate biometric characteristic of the alien."],[0,"(7) The term \"clerk of court\" means a clerk of a naturalization court."],[0,"(8) The terms \"Commissioner\" and \"Deputy Commissioner\" mean the Commissioner of Immigration and Naturalization and a Deputy Commissioner of Immigration and Naturalization, respectively."],[0,"(9) The term \"consular officer\" means any consular, diplomatic, or other officer or employee of the United States designated under regulations prescribed under authority contained in this chapter, for the purpose of issuing immigrant or nonimmigrant visas or, when used in subchapter III, for the purpose of adjudicating nationality."],[0,"(10) The term \"crewman\" means a person serving in any capacity on board a vessel or aircraft."],[0,"(11) The term \"diplomatic visa\" means a nonimmigrant visa bearing that title and issued to a nonimmigrant in accordance with such regulations as the Secretary of State may prescribe."],[0,"(12) The term \"doctrine\" includes, but is not limited to, policies, practices, purposes, aims, or procedures."],[0,"(13)(A) The terms \"admission\" and \"admitted\" mean, with respect to an alien, the lawful entry of the alien into the United States after inspection and authorization by an immigration officer."],[0,"(B) An alien who is paroled under section 1182(d)(5) of this title or permitted to land temporarily as an alien crewman shall not be considered to have been admitted."],[0,"(C) An alien lawfully admitted for permanent residence in the United States shall not be regarded as seeking an admission into the United States for purposes of the immigration laws unless the alien—"],[1,"(i) has abandoned or relinquished that status,"],[1,"(ii) has been absent from the United States for a continuous period in excess of 180 days,"],[1,"(iii) has engaged in illegal activity after having departed the United States,"],[1,"(iv) has departed from the United States while under legal process seeking removal of the alien from the United States, including removal proceedings under this chapter and extradition proceedings,"],[1,"(v) has committed an offense identified in section 1182(a)(2) of this title, unless since such offense the alien has been granted relief under section 1182(h) or 1229b(a) of this title, or"],[1,"(vi) is attempting to enter at a time or place other than as designated by immigration officers or has not been admitted to the United States after inspection and authorization by an immigration officer."],[0,"(14) The term \"foreign state\" includes outlying possessions of a foreign state, but self-governing dominions or territories under mandate or trusteeship shall be regarded as separate foreign states."],[0,"(15) The term \"immigrant\" means every alien except an alien who is within one of the following classes of nonimmigrant aliens—"],[1,"(A)(i) an ambassador, public minister, or career diplomatic or consular officer who has been accredited by a foreign government, recognized de jure by the United States and who is accepted by the President or by the Secretary of State, and the members of the alien's immediate family;"],[1,"(ii) upon a basis of reciprocity, other officials and employees who have been accredited by a foreign government recognized de jure by the United States, who are accepted by the Secretary of State, and the members of their immediate families; and"],[1,"(iii) upon a basis of reciprocity, attendants, servants, personal employees, and members of their immediate families, of the officials and employees who have a nonimmigrant status under (i) and (ii) above;"],[1,"(B) an alien (other than one coming for the purpose of study or of performing skilled or unskilled labor or as a representative of foreign press, radio, film, or other foreign information media coming to engage in such vocation) having a residence in a foreign country which he has no intention of abandoning and who is visiting the United States temporarily for business or temporarily for pleasure;"],[1,"(C)(i) an alien in immediate and continuous transit through the United States, for a period not to exceed 29 days;"],[1,"(ii) an alien who qualifies as a person entitled to pass in transit to and from the United Nations Headquarters District (as defined in section 4309a(e) of title 22) and foreign countries, under the provisions of paragraphs (3), (4), and (5) of section 11 of the Agreement regarding the Headquarters of the United Nations, done at Lake Success June 26, 1947 (61 Stat. 758); or"],[1,"(iii) an alien passing in transit through the United States to board a vessel on which the alien will perform, or to disembark from a vessel on which the alien performed, ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, for a period not to exceed 180 days;"],[1,"(D)(i) an alien crewman serving in good faith as such in a capacity required for normal operation and service on board a vessel, as defined in section 1288(a) of this title (other than a fishing vessel having its home port or an operating base in the United States), or aircraft, who intends to land temporarily and solely in pursuit of his calling as a crewman and to depart from the United States with the vessel or aircraft on which he arrived or some other vessel or aircraft;"],[1,"(ii) an alien crewman serving in good faith as such in any capacity required for normal operations and service aboard a fishing vessel having its home port or an operating base in the United States who intends to land temporarily in Guam or the Commonwealth of the Northern Mariana Islands and solely in pursuit of his calling as a crewman and to depart from Guam or the Commonwealth of the Northern Mariana Islands with the vessel on which he arrived; or"],[1,"(iii) an alien crewman performing ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, who intends to land temporarily solely in pursuit of the alien's responsibilities as a crewman and to depart from the United States on the vessel on which the alien arrived or on another vessel or aircraft, for a period not to exceed 180 days;"],[1,"(E) an alien entitled to enter the United States under and in pursuance of the provisions of a treaty of commerce and navigation between the United States and the foreign state of which the alien is a national (or, in the case of an alien who acquired the relevant nationality through a financial investment and who has not previously been granted status under this subparagraph, the foreign state of which the alien is a national and in which the alien has been domiciled for a continuous period of not less than 3 years at any point before applying for a nonimmigrant visa under this subparagraph), and the spouse and children of any such alien if accompanying or following to join such alien; (i) solely to carry on substantial trade, including trade in services or trade in technology, principally between the United States and the foreign state of which the alien is a national; (ii) solely to develop and direct the operations of an enterprise in which the alien has invested, or of an enterprise in which the alien is actively in the process of investing, a substantial amount of capital; or (iii) solely to perform services in a specialty occupation in the United States if the alien is a national of the Commonwealth of Australia and with respect to whom the Secretary of Labor determines and certifies to the Secretary of Homeland Security and the Secretary of State that the intending employer has filed with the Secretary of Labor an attestation under section 1182(t)(1) of this title;"],[1,"(F)(i) an alien having a residence in a foreign country which he has no intention of abandoning, who is a bona fide student qualified to pursue a full course of study and who seeks to enter the United States temporarily and solely for the purpose of pursuing such a course of study consistent with section 1184(l) 1 of this title at an established college, university, seminary, conservatory, academic high school, elementary school, or other academic institution or in an accredited language training program in the United States, particularly designated by him and approved by the Attorney General after consultation with the Secretary of Education, which institution or place of study shall have agreed to report to the Attorney General the termination of attendance of each nonimmigrant student, and if any such institution of learning or place of study fails to make reports promptly the approval shall be withdrawn, (ii) the alien spouse and minor children of any alien described in clause (i) if accompanying or following to join such an alien, and (iii) an alien who is a national of Canada or Mexico, who maintains actual residence and place of abode in the country of nationality, who is described in clause (i) except that the alien's qualifications for and actual course of study may be full or part-time, and who commutes to the United States institution or place of study from Canada or Mexico;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1101?type=usc&year=mostrecent&link-type=html"},"head":"§1101. Definitions","tname":"Aliens and Nationality","by":{"0":"2, 2","2":"2"}},{"t":"usc","label":"8 U.S.C. § 1103","url":"https://www.law.cornell.edu/uscode/text/8/1103","subs":["(a)","(a)(2)"],"by":{"0":"38, 37"}},{"t":"usc","label":"8 U.S.C. § 1226","url":"https://www.law.cornell.edu/uscode/text/8/1226","subs":["(a)","(c)","(c)(1)","(c)(2)","(e)"],"stext":{"head":"§1226. Apprehension and detention of aliens","paras":[[0,"(a) Arrest, detention, and release"],[0,"On a warrant issued by the Attorney General, an alien may be arrested and detained pending a decision on whether the alien is to be removed from the United States. Except as provided in subsection (c) and pending such decision, the Attorney General—"],[1,"(1) may continue to detain the arrested alien; and"],[1,"(2) may release the alien on—"],[2,"(A) bond of at least $1,500 with security approved by, and containing conditions prescribed by, the Attorney General; or"],[2,"(B) conditional parole; but"],[1,"(3) may not provide the alien with work authorization (including an \"employment authorized\" endorsement or other appropriate work permit), unless the alien is lawfully admitted for permanent residence or otherwise would (without regard to removal proceedings) be provided such authorization."],[0,"(b) Revocation of bond or parole"],[0,"The Attorney General at any time may revoke a bond or parole authorized under subsection (a), rearrest the alien under the original warrant, and detain the alien."],[0,"(c) Detention of criminal aliens"],[0,"(1) Custody"],[1,"The Attorney General shall take into custody any alien who—"],[2,"(A) is inadmissible by reason of having committed any offense covered in section 1182(a)(2) of this title,"],[2,"(B) is deportable by reason of having committed any offense covered in section 1227(a)(2)(A)(ii), (A)(iii), (B), (C), or (D) of this title,"],[2,"(C) is deportable under section 1227(a)(2)(A)(i) of this title on the basis of an offense for which the alien has been sentence 1 to a term of imprisonment of at least 1 year, or"],[2,"(D) is inadmissible under section 1182(a)(3)(B) of this title or deportable under section 1227(a)(4)(B) of this title,"],[1,"when the alien is released, without regard to whether the alien is released on parole, supervised release, or probation, and without regard to whether the alien may be arrested or imprisoned again for the same offense."],[0,"(2) Release"],[1,"The Attorney General may release an alien described in paragraph (1) only if the Attorney General decides pursuant to section 3521 of title 18 that release of the alien from custody is necessary to provide protection to a witness, a potential witness, a person cooperating with an investigation into major criminal activity, or an immediate family member or close associate of a witness, potential witness, or person cooperating with such an investigation, and the alien satisfies the Attorney General that the alien will not pose a danger to the safety of other persons or of property and is likely to appear for any scheduled proceeding. A decision relating to such release shall take place in accordance with a procedure that considers the severity of the offense committed by the alien."],[0,"(d) Identification of criminal aliens"],[0,"(1) The Attorney General shall devise and implement a system—"],[1,"(A) to make available, daily (on a 24-hour basis), to Federal, State, and local authorities the investigative resources of the Service to determine whether individuals arrested by such authorities for aggravated felonies are aliens;"],[1,"(B) to designate and train officers and employees of the Service to serve as a liaison to Federal, State, and local law enforcement and correctional agencies and courts with respect to the arrest, conviction, and release of any alien charged with an aggravated felony; and"],[1,"(C) which uses computer resources to maintain a current record of aliens who have been convicted of an aggravated felony, and indicates those who have been removed."],[0,"(2) The record under paragraph (1)(C) shall be made available—"],[1,"(A) to inspectors at ports of entry and to border patrol agents at sector headquarters for purposes of immediate identification of any alien who was previously ordered removed and is seeking to reenter the United States, and"],[1,"(B) to officials of the Department of State for use in its automated visa lookout system."],[0,"(3) Upon the request of the governor or chief executive officer of any State, the Service shall provide assistance to State courts in the identification of aliens unlawfully present in the United States pending criminal prosecution."],[0,"(e) Judicial review"],[0,"The Attorney General's discretionary judgment regarding the application of this section shall not be subject to review. No court may set aside any action or decision by the Attorney General under this section regarding the detention or release of any alien or the grant, revocation, or denial of bond or parole."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1226?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1226. Apprehension and detention of aliens","tname":"Aliens and Nationality","by":{"0":"20, 48, 20, 48, 20, 48, 20, 48, 20, 48, 20, 48","2":"8, 8, 9, passim, 8, 9, 2, 11, 7, 8"}},{"t":"usc","label":"8 U.S.C. § 1231","url":"https://www.law.cornell.edu/uscode/text/8/1231","subs":["(a)","(a)(1)","(a)(1)(A)","(a)(1)(B)","(a)(2)","(h)"],"stext":{"head":"§1231. Detention and removal of aliens ordered removed","paras":[[0,"(a) Detention, release, and removal of aliens ordered removed"],[0,"(1) Removal period"],[0,"(A) In general"],[2,"Except as otherwise provided in this section, when an alien is ordered removed, the Attorney General shall remove the alien from the United States within a period of 90 days (in this section referred to as the \"removal period\")."],[0,"(B) Beginning of period"],[2,"The removal period begins on the latest of the following:"],[3,"(i) The date the order of removal becomes administratively final."],[3,"(ii) If the removal order is judicially reviewed and if a court orders a stay of the removal of the alien, the date of the court's final order."],[3,"(iii) If the alien is detained or confined (except under an immigration process), the date the alien is released from detention or confinement."],[0,"(C) Suspension of period"],[2,"The removal period shall be extended beyond a period of 90 days and the alien may remain in detention during such extended period if the alien fails or refuses to make timely application in good faith for travel or other documents necessary to the alien's departure or conspires or acts to prevent the alien's removal subject to an order of removal."],[0,"(2) Detention"],[1,"During the removal period, the Attorney General shall detain the alien. Under no circumstance during the removal period shall the Attorney General release an alien who has been found inadmissible under section 1182(a)(2) or 1182(a)(3)(B) of this title or deportable under section 1227(a)(2) or 1227(a)(4)(B) of this title."],[0,"(3) Supervision after 90-day period"],[1,"If the alien does not leave or is not removed within the removal period, the alien, pending removal, shall be subject to supervision under regulations prescribed by the Attorney General. The regulations shall include provisions requiring the alien—"],[2,"(A) to appear before an immigration officer periodically for identification;"],[2,"(B) to submit, if necessary, to a medical and psychiatric examination at the expense of the United States Government;"],[2,"(C) to give information under oath about the alien's nationality, circumstances, habits, associations, and activities, and other information the Attorney General considers appropriate; and"],[2,"(D) to obey reasonable written restrictions on the alien's conduct or activities that the Attorney General prescribes for the alien."],[0,"(4) Aliens imprisoned, arrested, or on parole, supervised release, or probation"],[0,"(A) In general"],[2,"Except as provided in section 259(a) 1 of title 42 and paragraph (2),2 the Attorney General may not remove an alien who is sentenced to imprisonment until the alien is released from imprisonment. Parole, supervised release, probation, or possibility of arrest or further imprisonment is not a reason to defer removal."],[0,"(B) Exception for removal of nonviolent offenders prior to completion of sentence of imprisonment"],[2,"The Attorney General is authorized to remove an alien in accordance with applicable procedures under this chapter before the alien has completed a sentence of imprisonment—"],[3,"(i) in the case of an alien in the custody of the Attorney General, if the Attorney General determines that (I) the alien is confined pursuant to a final conviction for a nonviolent offense (other than an offense related to smuggling or harboring of aliens or an offense described in section 1101(a)(43)(B), (C), (E), (I), or (L) of this title 3 and (II) the removal of the alien is appropriate and in the best interest of the United States; or"],[3,"(ii) in the case of an alien in the custody of a State (or a political subdivision of a State), if the chief State official exercising authority with respect to the incarceration of the alien determines that (I) the alien is confined pursuant to a final conviction for a nonviolent offense (other than an offense described in section 1101(a)(43)(C) or (E) of this title), (II) the removal is appropriate and in the best interest of the State, and (III) submits a written request to the Attorney General that such alien be so removed."],[0,"(C) Notice"],[2,"Any alien removed pursuant to this paragraph shall be notified of the penalties under the laws of the United States relating to the reentry of deported aliens, particularly the expanded penalties for aliens removed under subparagraph (B)."],[0,"(D) No private right"],[2,"No cause or claim may be asserted under this paragraph against any official of the United States or of any State to compel the release, removal, or consideration for release or removal of any alien."],[0,"(5) Reinstatement of removal orders against aliens illegally reentering"],[1,"If the Attorney General finds that an alien has reentered the United States illegally after having been removed or having departed voluntarily, under an order of removal, the prior order of removal is reinstated from its original date and is not subject to being reopened or reviewed, the alien is not eligible and may not apply for any relief under this chapter, and the alien shall be removed under the prior order at any time after the reentry."],[0,"(6) Inadmissible or criminal aliens"],[1,"An alien ordered removed who is inadmissible under section 1182 of this title, removable under section 1227(a)(1)(C), 1227(a)(2), or 1227(a)(4) of this title or who has been determined by the Attorney General to be a risk to the community or unlikely to comply with the order of removal, may be detained beyond the removal period and, if released, shall be subject to the terms of supervision in paragraph (3)."],[0,"(7) Employment authorization"],[1,"No alien ordered removed shall be eligible to receive authorization to be employed in the United States unless the Attorney General makes a specific finding that—"],[2,"(A) the alien cannot be removed due to the refusal of all countries designated by the alien or under this section to receive the alien, or"],[2,"(B) the removal of the alien is otherwise impracticable or contrary to the public interest."],[0,"(b) Countries to which aliens may be removed"],[0,"(1) Aliens arriving at the United States"],[1,"Subject to paragraph (3)—"],[0,"(A) In general"],[2,"Except as provided by subparagraphs (B) and (C), an alien who arrives at the United States and with respect to whom proceedings under section 1229a of this title were initiated at the time of such alien's arrival shall be removed to the country in which the alien boarded the vessel or aircraft on which the alien arrived in the United States."],[0,"(B) Travel from contiguous territory"],[2,"If the alien boarded the vessel or aircraft on which the alien arrived in the United States in a foreign territory contiguous to the United States, an island adjacent to the United States, or an island adjacent to a foreign territory contiguous to the United States, and the alien is not a native, citizen, subject, or national of, or does not reside in, the territory or island, removal shall be to the country in which the alien boarded the vessel that transported the alien to the territory or island."],[0,"(C) Alternative countries"],[2,"If the government of the country designated in subparagraph (A) or (B) is unwilling to accept the alien into that country's territory, removal shall be to any of the following countries, as directed by the Attorney General:"],[3,"(i) The country of which the alien is a citizen, subject, or national."],[3,"(ii) The country in which the alien was born."],[3,"(iii) The country in which the alien has a residence."],[3,"(iv) A country with a government that will accept the alien into the country's territory if removal to each country described in a previous clause of this subparagraph is impracticable, inadvisable, or impossible."],[0,"(2) Other aliens"],[1,"Subject to paragraph (3)—"],[0,"(A) Selection of country by alien"],[2,"Except as otherwise provided in this paragraph—"],[3,"(i) any alien not described in paragraph (1) who has been ordered removed may designate one country to which the alien wants to be removed, and"],[3,"(ii) the Attorney General shall remove the alien to the country the alien so designates."],[0,"(B) Limitation on designation"],[2,"An alien may designate under subparagraph (A)(i) a foreign territory contiguous to the United States, an adjacent island, or an island adjacent to a foreign territory contiguous to the United States as the place to which the alien is to be removed only if the alien is a native, citizen, subject, or national of, or has resided in, that designated territory or island."],[0,"(C) Disregarding designation"],[2,"The Attorney General may disregard a designation under subparagraph (A)(i) if—"],[3,"(i) the alien fails to designate a country promptly;"],[3,"(ii) the government of the country does not inform the Attorney General finally, within 30 days after the date the Attorney General first inquires, whether the government will accept the alien into the country;"],[3,"(iii) the government of the country is not willing to accept the alien into the country; or"],[3,"(iv) the Attorney General decides that removing the alien to the country is prejudicial to the United States."],[0,"(D) Alternative country"],[2,"If an alien is not removed to a country designated under subparagraph (A)(i), the Attorney General shall remove the alien to a country of which the alien is a subject, national, or citizen unless the government of the country—"],[3,"(i) does not inform the Attorney General or the alien finally, within 30 days after the date the Attorney General first inquires or within another period of time the Attorney General decides is reasonable, whether the government will accept the alien into the country; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1231?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§1231. Detention and removal of aliens ordered removed","tname":"Aliens and Nationality","by":{"0":"20, 48, 20, 48, 20, 48, 20, 48, 20, 48, 20, 48, 20, 48","2":"8, 13, 2, 8, 11, 12, 8"}},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","subs":["(g)"],"stext":{"head":"§1252. Judicial review of orders of removal","paras":[[0,"(a) Applicable provisions"],[0,"(1) General orders of removal"],[1,"Judicial review of a final order of removal (other than an order of removal without a hearing pursuant to section 1225(b)(1) of this title) is governed only by chapter 158 of title 28, except as provided in subsection (b) and except that the court may not order the taking of additional evidence under section 2347(c) of such title."],[0,"(2) Matters not subject to judicial review"],[0,"(A) Review relating to section 1225(b)(1)"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, no court shall have jurisdiction to review—"],[3,"(i) except as provided in subsection (e), any individual determination or to entertain any other cause or claim arising from or relating to the implementation or operation of an order of removal pursuant to section 1225(b)(1) of this title,"],[3,"(ii) except as provided in subsection (e), a decision by the Attorney General to invoke the provisions of such section,"],[3,"(iii) the application of such section to individual aliens, including the determination made under section 1225(b)(1)(B) of this title, or"],[3,"(iv) except as provided in subsection (e), procedures and policies adopted by the Attorney General to implement the provisions of section 1225(b)(1) of this title."],[0,"(B) Denials of discretionary relief"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), and regardless of whether the judgment, decision, or action is made in removal proceedings, no court shall have jurisdiction to review—"],[3,"(i) any judgment regarding the granting of relief under section 1182(h), 1182(i), 1229b, 1229c, or 1255 of this title, or"],[3,"(ii) any other decision or action of the Attorney General or the Secretary of Homeland Security the authority for which is specified under this subchapter to be in the discretion of the Attorney General or the Secretary of Homeland Security, other than the granting of relief under section 1158(a) of this title."],[0,"(C) Orders against criminal aliens"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), no court shall have jurisdiction to review any final order of removal against an alien who is removable by reason of having committed a criminal offense covered in section 1182(a)(2) or 1227(a)(2)(A)(iii), (B), (C), or (D) of this title, or any offense covered by section 1227(a)(2)(A)(ii) of this title for which both predicate offenses are, without regard to their date of commission, otherwise covered by section 1227(a)(2)(A)(i) of this title."],[0,"(D) Judicial review of certain legal claims"],[2,"Nothing in subparagraph (B) or (C), or in any other provision of this chapter (other than this section) which limits or eliminates judicial review, shall be construed as precluding review of constitutional claims or questions of law raised upon a petition for review filed with an appropriate court of appeals in accordance with this section."],[0,"(3) Treatment of certain decisions"],[1,"No alien shall have a right to appeal from a decision of an immigration judge which is based solely on a certification described in section 1229a(c)(1)(B) of this title."],[0,"(4) Claims under the United Nations Convention"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of any cause or claim under the United Nations Convention Against Torture and Other Forms of Cruel, Inhuman, or Degrading Treatment or Punishment, except as provided in subsection (e)."],[0,"(5) Exclusive means of review"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of an order of removal entered or issued under any provision of this chapter, except as provided in subsection (e). For purposes of this chapter, in every provision that limits or eliminates judicial review or jurisdiction to review, the terms \"judicial review\" and \"jurisdiction to review\" include habeas corpus review pursuant to section 2241 of title 28, or any other habeas corpus provision, sections 1361 and 1651 of such title, and review pursuant to any other provision of law (statutory or nonstatutory)."],[0,"(b) Requirements for review of orders of removal"],[0,"With respect to review of an order of removal under subsection (a)(1), the following requirements apply:"],[0,"(1) Deadline"],[1,"The petition for review must be filed not later than 30 days after the date of the final order of removal."],[0,"(2) Venue and forms"],[1,"The petition for review shall be filed with the court of appeals for the judicial circuit in which the immigration judge completed the proceedings. The record and briefs do not have to be printed. The court of appeals shall review the proceeding on a typewritten record and on typewritten briefs."],[0,"(3) Service"],[0,"(A) In general"],[2,"The respondent is the Attorney General. The petition shall be served on the Attorney General and on the officer or employee of the Service in charge of the Service district in which the final order of removal under section 1229a of this title was entered."],[0,"(B) Stay of order"],[2,"Service of the petition on the officer or employee does not stay the removal of an alien pending the court's decision on the petition, unless the court orders otherwise."],[0,"(C) Alien's brief"],[2,"The alien shall serve and file a brief in connection with a petition for judicial review not later than 40 days after the date on which the administrative record is available, and may serve and file a reply brief not later than 14 days after service of the brief of the Attorney General, and the court may not extend these deadlines except upon motion for good cause shown. If an alien fails to file a brief within the time provided in this paragraph, the court shall dismiss the appeal unless a manifest injustice would result."],[0,"(4) Scope and standard for review"],[1,"Except as provided in paragraph (5)(B)—"],[2,"(A) the court of appeals shall decide the petition only on the administrative record on which the order of removal is based,"],[2,"(B) the administrative findings of fact are conclusive unless any reasonable adjudicator would be compelled to conclude to the contrary,"],[2,"(C) a decision that an alien is not eligible for admission to the United States is conclusive unless manifestly contrary to law, and"],[2,"(D) the Attorney General's discretionary judgment whether to grant relief under section 1158(a) of this title shall be conclusive unless manifestly contrary to the law and an abuse of discretion."],[1,"No court shall reverse a determination made by a trier of fact with respect to the availability of corroborating evidence, as described in section 1158(b)(1)(B), 1229a(c)(4)(B), or 1231(b)(3)(C) of this title, unless the court finds, pursuant to subsection (b)(4)(B), that a reasonable trier of fact is compelled to conclude that such corroborating evidence is unavailable."],[0,"(5) Treatment of nationality claims"],[0,"(A) Court determination if no issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds from the pleadings and affidavits that no genuine issue of material fact about the petitioner's nationality is presented, the court shall decide the nationality claim."],[0,"(B) Transfer if issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds that a genuine issue of material fact about the petitioner's nationality is presented, the court shall transfer the proceeding to the district court of the United States for the judicial district in which the petitioner resides for a new hearing on the nationality claim and a decision on that claim as if an action had been brought in the district court under section 2201 of title 28."],[0,"(C) Limitation on determination"],[2,"The petitioner may have such nationality claim decided only as provided in this paragraph."],[0,"(6) Consolidation with review of motions to reopen or reconsider"],[1,"When a petitioner seeks review of an order under this section, any review sought of a motion to reopen or reconsider the order shall be consolidated with the review of the order."],[0,"(7) Challenge to validity of orders in certain criminal proceedings"],[0,"(A) In general"],[2,"If the validity of an order of removal has not been judicially decided, a defendant in a criminal proceeding charged with violating section 1253(a) of this title may challenge the validity of the order in the criminal proceeding only by filing a separate motion before trial. The district court, without a jury, shall decide the motion before trial."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1252?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1252. Judicial review of orders of removal","tname":"Aliens and Nationality","by":{"0":"20, 48, 27, 27, 27, 27","2":"2, 20, 22, 23, 22"}},{"t":"usc","label":"8 U.S.C. § 1330","url":"https://www.law.cornell.edu/uscode/text/8/1330","subs":["(b)(3)(A)(i)"],"by":{"0":"31"}},{"t":"usc","label":"8 U.S.C. § 1357","url":"https://www.law.cornell.edu/uscode/text/8/1357","subs":["(g)(1)","(g)(10)(B)"],"by":{"0":"31, 31"}},{"t":"usc","label":"8 U.S.C. § 1536","url":"https://www.law.cornell.edu/uscode/text/8/1536","subs":["(a)(3)(B)"],"by":{"0":"31"}},{"t":"usc","label":"6 U.S.C. § 112","url":"https://www.law.cornell.edu/uscode/text/6/112","subs":["(a)","(b)(1)"],"by":{"0":"38, 38"}},{"t":"usc","label":"6 U.S.C. § 202","url":"https://www.law.cornell.edu/uscode/text/6/202","subs":["(5)"],"stext":{"head":"§202. Border, maritime, and transportation responsibilities","paras":[[0,"The Secretary shall be responsible for the following:"],[1,"(1) Preventing the entry of terrorists and the instruments of terrorism into the United States."],[1,"(2) Securing the borders, territorial waters, ports, terminals, waterways, and air, land, and sea transportation systems of the United States, including managing and coordinating those functions transferred to the Department at ports of entry."],[1,"(3) Carrying out the immigration enforcement functions vested by statute in, or performed by, the Commissioner of Immigration and Naturalization (or any officer, employee, or component of the Immigration and Naturalization Service) immediately before the date on which the transfer of functions specified under section 251 of this title takes effect."],[1,"(4) Establishing and administering rules, in accordance with section 236 of this title, governing the granting of visas or other forms of permission, including parole, to enter the United States to individuals who are not a citizen or an alien lawfully admitted for permanent residence in the United States."],[1,"(5) Establishing national immigration enforcement policies and priorities."],[1,"(6) Except as provided in part C of this subchapter, administering the customs laws of the United States."],[1,"(7) Conducting the inspection and related administrative functions of the Department of Agriculture transferred to the Secretary of Homeland Security under section 231 of this title."],[1,"(8) In carrying out the foregoing responsibilities, ensuring the speedy, orderly, and efficient flow of lawful traffic and commerce."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/6/202?type=usc&year=mostrecent&link-type=html"},"head":"§202. Border, maritime, and transportation responsibilities","tname":"Domestic Security","by":{"0":"2, 30, 38","2":"9, 13"}},{"t":"usc","label":"28 U.S.C. § 1253","url":"https://www.law.cornell.edu/uscode/text/28/1253","stext":{"head":"§1253. Direct appeals from decisions of three-judge courts","paras":[[0,"Except as otherwise provided by law, any party may appeal to the Supreme Court from an order granting or denying, after notice and hearing, an interlocutory or permanent injunction in any civil action, suit or proceeding required by any Act of Congress to be heard and determined by a district court of three judges."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1253?type=usc&year=mostrecent&link-type=html"},"head":"§1253. Direct appeals from decisions of three-judge courts","tname":"Judiciary and Judicial Procedure","by":{"0":"46","2":"21"}},{"t":"usc","label":"28 U.S.C. § 2342","url":"https://www.law.cornell.edu/uscode/text/28/2342","by":{"0":"42"}},{"t":"reg","label":"8 C.F.R. § 2.1","url":"https://www.ecfr.gov/current/title-8/section-2.1","by":{"0":"38"}},{"t":"reg","label":"Continued Detention of Aliens Subject to Final Orders of Removal, 66 Fed. Reg. 56,967","url":"https://www.govinfo.gov/link/fr/66/56967","by":{"0":"32"}},{"t":"case","label":"Alaska v. Dep’t of Transp.","cite":"868 F.2d 441","y":1989,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/868/441/","by":{"1":"37"}},{"t":"case","label":"Almendarez-Torres v. United States","cite":"523 U.S. 224","y":1998,"id":"1997/96-6839","sc":1,"sum":"The Court held that subsection (b)(2) of 8 USC section 1326(a) is a penalty provision, which authorizes a court to increase the sentence for a recidivist, and does not define a separate crime. \"[W]e note that the relevant statutory subject matter is recidivism,\" wrote Justice Breyer, \"[t]hat subject matter -- prior commission of a serious crime -- is as typical a sentencing factor as one might imagine.\" Therefore, neither subsection (b)(2) nor the due process clause of the Fifth Amendment required that the government charge a prior aggravated felony conviction in the alien's indictment for the imposition of a sentence more than 2 years.","sumSrc":"Oyez","by":{"1":"44"}},{"t":"case","label":"Aragon v. Tillerson","cite":"240 F. Supp. 3d 99","y":2017,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/240/99/","by":{"1":"41"}},{"t":"case","label":"Atl. Richfield Co. v. Christian","cite":"140 S. Ct. 1335","y":2020,"id":"2019/17-1498","sc":1,"sum":"The Court held that the landowners in this case were potentially responsible parties under the Comprehensive Environmental Response, Compensation, and Liability Act (CERCLA) and thus need the Environmental Protection Agency’s approval to take remedial action.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Azar v. Allina Health Servs.","cite":"139 S. Ct. 1804","y":2019,"id":"2018/17-1484","sc":1,"sum":"Because the Department of Health and Human Services neglected its statutory notice-and-comment obligations when it revealed a new policy that dramatically—and retroactively—reduced Medicare payments to hospitals serving low-income patients, its policy must be vacated.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"38"}},{"t":"case","label":"Bowen v. Massachusetts","cite":"487 U.S. 879","y":1988,"id":"1987/87-712","sc":1,"sum":"The federal contribution (referred to as a \"reimbursement\") to a State's Medicaid program takes the form of advances based on the State's estimate of its future expenditures for covered services. Overpayments may be withheld from future advances, or, if a disallowance dispute develops, may be retained by the State at its option pending resolution of the dispute. After Massachusetts was reimbursed by the Department …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22"}},{"t":"case","label":"Brnovich v. Democratic Nat’l Comm.","cite":"141 S. Ct. 2321","y":2021,"id":"2020/19-1257","sc":1,"op":1,"sum":"Arizona’s challenged voting regulations governing precinct-based election-day voting (rejecting ballots cast in the wrong precinct) and early mail-in voting (making it a crime for anyone other than an authorized proxy to possess the early ballot of another voter) do not violate §2 of the Voting Rights Act of 1965; Arizona House Bill 2023 (enacting the early mail-in voting regulations) was not enacted with a racially discriminatory purpose.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"12, 15"}},{"t":"case","label":"California v. Arizona","cite":"452 U.S. 431","y":1981,"id":"1980/78_orig","sc":1,"by":{"1":"43"}},{"t":"case","label":"Campos v. INS","cite":"62 F.3d 311","y":1995,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/62/311/","by":{"1":"28"}},{"t":"case","label":"Clapper v. Amnesty Int’l USA","cite":"568 U.S. 398","y":2013,"id":"2012/11-1025","sc":1,"op":2,"sum":"The Court held that the respondents lacked Article III standing against FISA because fear of intercepted communication and costs incurred to avoid intercepted communications are not injuries.","sumSrc":"Oyez","by":{"1":"12"}},{"t":"case","label":"Cooper v. Harris","cite":"137 S. Ct. 1455","y":2017,"id":"2016/15-1262","sc":1,"sum":"The Court determined that the district court did not error in determining that North Carolina’s new districting plan constituted an unconstitutional racial gerrymander, and neither claim nor issue preclusion based on the state court case dictate the outcome of this case.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Cream Wipt Food Prods. Co. v. Fed. Sec. Adm’r","cite":"187 F.2d 789","y":1951,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/187/789/","by":{"1":"40","2":"19"}},{"t":"case","label":"Crowley Caribbean Transp. v. Pena","cite":"37 F.3d 671","y":1994,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/37/671/","by":{"1":"31"}},{"t":"case","label":"Czyzewski v. Jevic Holding Corp.","cite":"137 S. Ct. 973","y":2017,"id":"2016/15-649","sc":1,"sum":"The Court determined that bankruptcy court cannot authorize a distribution of settlement proceeds in a manner that does not comply with the Bankruptcy Code’s priority distribution scheme.","sumSrc":"Oyez","by":{"1":"12-13"}},{"t":"case","label":"Data Mktg. P’ship, LP v. U.S. Dep’t of Labor","cite":"45 F.4th 846","y":2022,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/45/846/","op":1,"by":{"1":"42, 46"}},{"t":"case","label":"DHS v. Thuraissigiam","cite":"140 S. Ct. 1959","y":2020,"id":"2019/19-161","sc":1,"sum":"The Court held that 8 U.S.C. § 1252(e)(2) as applied to the respondent Thuraissigiam does not violate the Suspension Clause of the Constitution.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"eBay Inc. v. MercExchange, LLC","cite":"547 U.S. 388","y":2006,"id":"2005/05-130","sc":1,"op":1,"sum":"Held that the appeals court's general rule was an unwarranted departure from the traditional four-part test applied to determine whether an injunction is necessary.","sumSrc":"Oyez","by":{"1":"46, 48"}},{"t":"case","label":"Fogo De Chao (Holdings), Inc. v. DHS","cite":"211 F. Supp. 3d 31","y":2016,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/211/31/","by":{"1":"41"}},{"t":"case","label":"Franchise Tax Bd. of Cal. v. Hyatt","cite":"139 S. Ct. 1485","y":2019,"id":"2018/17-1299","sc":1,"sum":"Nevada v. Hall, 440 U. S. 410, is overruled; States retain their sovereign immunity from private suits brought in courts of other States.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"19"}},{"t":"case","label":"Galvez v. Lewis","cite":"56 F. Supp. 2d 637","y":1999,"court":"E.D. Va.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/56/637/","by":{"1":"4, 31"}},{"t":"case","label":"Gen. Elec. Co. v. EPA","cite":"290 F.3d 377","y":2002,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/290/377/","by":{"1":"38"}},{"t":"case","label":"Gerber v. Norton","cite":"294 F.3d 173","y":2002,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/294/173/","by":{"1":"36"}},{"t":"case","label":"Getty v. Fed. Sav. & Loan","cite":"805 F.2d 1050","y":1986,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/805/1050/","by":{"1":"36"}},{"t":"case","label":"Guerrero-Lasprilla v. Barr","cite":"140 S. Ct. 1062","y":2020,"id":"2019/18-776","sc":1,"sum":"The Court held that the phrase “questions of law” in the Immigration and Nationality Act’s Limited Review Provision, 8 U. S. C. §1252(a)(2)(D), includes the application of a legal standard to undisputed or established facts.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Harmon v. Thornburgh","cite":"878 F.2d 484","y":1989,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/878/484/","by":{"1":"42, 46"}},{"t":"case","label":"INS v. Nat’l Ctr. for Immigrants’ Rights, Inc.","cite":"502 U.S. 183","y":1991,"id":"1991/90-1090","sc":1,"sum":"The regulation on its face is consistent with the Attorney General's statutory authority.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"44"}},{"t":"case","label":"Japan Whaling Ass’n v. Am. Cetacean Soc’y","cite":"478 U.S. 221","y":1986,"id":"1985/85-954","sc":1,"sum":"The International Convention for the Regulation of Whaling (ICRW) included a Schedule regulating whale harvesting practices of member nations (including the United States and Japan) and setting harvest limits for various whale species. It also established the International Whaling Commission (IWC) and authorized it to set harvest quotas. However, the IWC has no power to impose sanctions for quota violations, and any …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"29"}},{"t":"case","label":"Kenney v. Glickman","cite":"96 F.3d 1118","y":1996,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/96/1118/","by":{"1":"31"}},{"t":"case","label":"Kingdomware Techs., Inc. v. United States","cite":"579 U.S. 162","y":2016,"id":"2015/14-916","sc":1,"sum":"The Court determined that the Court had jurisdiction to address the merits of the case even if the contracts had already been performed, and the Department of Veterans Affairs’ “set-aside” for veteran-owned businesses is mandatory.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Kirtsaeng v. John Wiley & Sons, Inc.","cite":"568 U.S. 519","y":2013,"id":"2012/11-697","sc":1,"op":1,"sum":"The Court found that there is not geographical restriction on the \"first sale\" copyright doctrine.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Kisor v. Wilkie","cite":"139 S. Ct. 2400","y":2019,"id":"2018/18-15","sc":1,"op":1,"sum":"Auer v. Robbins, 519 U. S. 452, and Bowles v. Seminole Rock & Sand Co., 325 U. S. 410—under which deference is given to an agency’s reasonable reading of its own genuinely ambiguous regulations—are not overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"36"}},{"t":"case","label":"Kucana v. Holder","cite":"558 U.S. 233","y":2010,"id":"2009/08-911","sc":1,"sum":"The Court held that 8 U.S.C. Section 1252(a)(2)(B)(ii) does not preclude federal courts from hearing cases specified by the Attorney General, only cases that are specified by statute.","sumSrc":"Oyez","by":{"1":"27, 28"}},{"t":"case","label":"Lujan v. National Wildlife Fed’n","cite":"497 U.S. 871","y":1990,"id":"1989/89-640","sc":1,"sum":"In a 5-to-4 decision written by Justice Antonin Scalia, the Supreme Court held that NWF did not have standing to challenge the land-use designations. The two timely affidavits were not enough to show that the group members had actually been affected by the BLM decisions.","sumSrc":"Oyez","by":{"1":"42","2":"20"}},{"t":"case","label":"Mach Mining, LLC v. EEOC","cite":"575 U.S. 480","y":2015,"id":"2014/13-1019","sc":1,"sum":"The Court held that judicial review of the Equal Employment Opportunity Commission’s efforts at conciliation is appropriate, but such review must be limited to the narrow requirements that Title VII imposes.","sumSrc":"Oyez","by":{"1":"46, 47"}},{"t":"case","label":"McLouth Steel Prod. Corp. v. Thomas","cite":"838 F.2d 1317","y":1988,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/838/1317/","by":{"1":"38"}},{"t":"case","label":"Me. Cmty. Health Options v. United States","cite":"140 S. Ct. 1308","y":2020,"id":"2019/18-1023","sc":1,"sum":"The Court held that the federal government has an obligation to pay the insurance carriers in this case for losses incurred under the \"Risk Corridors\" program of the Affordable Care Act as a result of their participation in the health care marketplace.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Medellín v. Texas","cite":"552 U.S. 491","y":2008,"id":"2007/06-984","sc":1,"sum":"The Court held that the signed Protocol of the Vienna Convention did not make the treaty self-executing and, therefore, the treaty is not binding upon state courts until it is enacted into law by Congress.","sumSrc":"Oyez","by":{"1":"34"}},{"t":"case","label":"39 Nat’l Mining Ass’n v. U.S. Army Corps of Eng’rs","cite":"145 F.3d 1399","y":1998,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/145/1399/","by":{"1":"42"}},{"t":"case","label":"Nat’l Park Hosp. Ass’n v. Dep’t of Interior","cite":"538 U.S. 803","y":2003,"id":"2002/02-196","sc":1,"sum":"The Court held that the controversy was not yet ripe for judicial resolution.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"New York v. United States","cite":"505 U.S. 144","y":1992,"id":"1991/91-543","sc":1,"op":2,"sum":"The Court upheld two of the three provisions of the Act under review, reasoning that Congress had the authority under the Commerce Clause to use financial rewards and access to disposal sites as incentives for state waste management.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"NFIB v. Sebelius","cite":"567 U.S. 519","y":2012,"id":"2011/11-393","sc":1,"op":1,"sum":"Cases in which the Court held that the minimum coverage requirement of the Affordable Care Act was constitutional, that Congress had the power to enforce the taxation of most Americans that did not buy the minimum level of coverage, and that the federal government exceeded its power by pressuring States into accepting conditions that Congress could not impose directly by threatening to withhold all federal funding under Medicaid.","sumSrc":"Oyez","by":{"1":"20-21"}},{"t":"case","label":"(ctd.): Nken v. Holder","cite":"556 U.S. 418","y":2009,"id":"2008/08-681","sc":1,"sum":"The Court held that a court of appeals' decision to stay an alien's removal pending consideration of the alien's petition for review is governed by the 4-factor traditional test.","sumSrc":"Oyez","by":{"1":"48"}},{"t":"case","label":"O.A. v. Trump","cite":"404 F. Supp. 3d 109","y":2019,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/404/109/","by":{"1":"43"}},{"t":"case","label":"OSG Bulk Ships v. United States","cite":"132 F.3d 808","y":1998,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/132/808/","by":{"1":"31"}},{"t":"case","label":"RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"sum":"The Court held that a company could not obtain confirmation of a Chapter 11 bankruptcy plan that provided for the sale of its assets free from lien without permitting a bank to credit-bid at the sale.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Rapanos v. United States","cite":"547 U.S. 715","y":2006,"id":"2005/04-1034","sc":1,"sum":"The plurality rejected the argument that only actually-navigable waters can be regulated by the Clean Water Act, but also held that the word \"navigable\" in the Act cannot be divested of all meaning. The plurality held that the definitional term \"waters of the United States\" can only refer to \"relatively permanent, standing or flowing bodies of water,\" not \"occasional,\" \"intermittent,\" or \"ephemeral\" flows.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"Salazar v. Ramah Navajo Chapter","cite":"567 U.S. 182","y":2012,"id":"2011/11-551","sc":1,"op":1,"sum":"The Court held that, under the Indian Self-Determination and Education Assistance Act, the government is required to pay all of the contract support costs incurred by a tribal contractor if payment of those costs would exceed the statutory cap on the appropriations available to pay them.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Salinas v. U.S. R.R. Ret. Bd.","cite":"141 S. Ct. 691","y":2021,"id":"2020/19-199","sc":1,"sum":"The U. S. Railroad Retirement Board’s denial of a request to reopen a prior benefits determination under the Railroad Retirement Act of 1974 and the Railroad Unemployment Insurance Act is subject to judicial review.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"46"}},{"t":"case","label":"Sarnoff v. Connally","cite":"457 F.2d 809","y":1972,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/457/809/","by":{"1":"20"}},{"t":"case","label":"Smith v. Berryhill","cite":"139 S. Ct. 1765","y":2019,"id":"2018/17-1606","sc":1,"sum":"A Social Security Administration Appeals Council dismissal on timeliness grounds of a request for review after a claimant has had an administrative law judge hearing on the merits qualifies as a “final decision . . . made after a hearing” for purposes of allowing judicial review under 42 U. S. C. §405(g).","sumSrc":"Holding (supremecourt.gov)","by":{"1":"46-47"}},{"t":"case","label":"(ctd.): Soler v. Scott","cite":"942 F.2d 597","y":1991,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/942/597/","by":{"1":"28"}},{"t":"case","label":"Spokeo, Inc. v. Robins","cite":"578 U.S. 330","y":2016,"id":"2015/13-1339","sc":1,"op":1,"sum":"The Court held that lower courts need to consider the elements of Article III standing analysis separately in determining whether standing is sufficient for a federal court to hear the case.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Territory of Guam v. United States","cite":"141 S. Ct. 1608","y":2021,"id":"2020/20-382","sc":1,"sum":"A settlement of environmental liabilities must resolve a specific liability under the Comprehensive Environmental Response, Compensation, and Liability Act of 1980 to give rise to a contribution action under that Act.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"33"}},{"t":"case","label":"Texas v. United States","cite":"14 F.4th 332","y":2021,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/14/332/","by":{"1":"7"}},{"t":"case","label":"Texas v. United States","cite":"24 F.4th 407","y":2021,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/24/407/","by":{"1":"7"}},{"t":"case","label":"Texas v. United States","cite":"555 F. Supp. 3d 351","y":2021,"court":"S.D. Tex.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/555/351/","by":{"1":"7, 43"}},{"t":"case","label":"Texas v. United States","cite":"2022 WL 517281","y":2022,"court":"5th Cir. Feb. 11","by":{"1":"7-8"}},{"t":"case","label":"Texas v. United States","cite":"2021 WL 1309766","y":2021,"court":"S.D. Tex. Apr. 6","by":{"1":"7"}},{"t":"case","label":"U.S. Army Corps of Eng’rs v. Hawkes Co.","cite":"578 U.S. 590","y":2016,"id":"2015/15-290","sc":1,"sum":"The Court determined that the Army Corps of Engineers’ jurisdictional determination that a property constituted “water of the United States” was a final agency action subject to judicial review under the Administrative Procedure Act.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"U.S. Telecom Ass’n v. FCC","cite":"400 F.3d 29","y":2005,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/400/29/","by":{"1":"37"}},{"t":"case","label":"(ctd.): United States v. Smith","cite":"27 F. Cas. 1192","y":1806,"court":"C.C.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Cas./27/1192/","op":1,"by":{"1":"31"}},{"t":"case","label":"United States v. Texas","cite":"579 U.S. 547","y":2016,"id":"2015/15-674","sc":1,"op":1,"sum":"A case in which the equally divided Court affirmed the lower court's judgment that the Deferred Action for Parents of Americans and Lawful Permanent Residents (DAPA) program was arbitrary and capricious, and failed to undergo notice-and-comment procedures as required by the Administrative Procedure Act.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"Util. Air Regul. Grp. v. EPA","cite":"573 U.S. 302","y":2014,"id":"2013/12-1146","sc":1,"sum":"The Court held that, under the Clean Air Act, the EPA is not required to include greenhouse gas emissions every time it mentions air pollution.","sumSrc":"Oyez","by":{"1":"1"}},{"t":"case","label":"Uzuegbunam v. Preczewski","cite":"141 S. Ct. 792","y":2021,"id":"2020/19-968","sc":1,"op":1,"sum":"A request for nominal damages satisfies the redressability element necessary for Article III standing where a plaintiff’s claim is based on a completed violation of a legal right.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"13, 14, 15"}},{"t":"case","label":"V.I. Tel. Corp. v. FCC","cite":"444 F.3d 666","y":2006,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/444/666/","by":{"1":"41"}},{"t":"case","label":"Zadvydas v. Davis","cite":"533 U.S. 678","y":2001,"id":"2000/99-7791","sc":1,"ar":2,"sum":"The Court held that \"the statute, read in light of the Constitution's demands, limits an alien's post-removal-period detention to a period reasonably necessary to bring about that alien's removal from the United States\" and \"does not permit indefinite detention.\" \"Based on our conclusion that indefinite detention of aliens in the former category would raise serious constitutional concerns, we construe the statute to contain an implicit 'reasonable time' limitation, the application of which is subject to federal court review,\" wrote Justice Breyer.","sumSrc":"Oyez","by":{"1":"4, 5"}},{"t":"const","label":"Article II, Section 3","clauses":[["take-care","Take Care Clause"]],"text":"He shall from time to time give to the Congress Information of the State of the Union, and recommend to their Consideration such Measures as he shall judge necessary and expedient; he may, on extraordinary Occasions, convene both Houses, or either of them, and in Case of Disagreement between them, with Respect to the Time of Adjournment, he may adjourn them to such Time as he shall think proper; he shall receive Ambassadors and other public Ministers; he shall take Care that the Laws be faithfully executed, and shall Commission all the Officers of the United States.","by":{"1":"31"}},{"t":"usc","label":"28 U.S.C. § 1651","url":"https://www.law.cornell.edu/uscode/text/28/1651","stext":{"head":"§1651. Writs","paras":[[0,"(a) The Supreme Court and all courts established by Act of Congress may issue all writs necessary or appropriate in aid of their respective jurisdictions and agreeable to the usages and principles of law."],[0,"(b) An alternative writ or rule nisi may be issued by a justice or judge of a court which has jurisdiction."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1651?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1651. Writs","tname":"Judiciary and Judicial Procedure","by":{"1":"47"}},{"t":"law","label":"Pub. L. No. 103-416","by":{"1":"28"}},{"t":"law","label":"Pub. L. No. 104-108","url":"https://www.govinfo.gov/link/plaw/104/public/108","by":{"1":"4"}},{"t":"case","label":"Oral Arg. Tr., Nielsen v. Preap","cite":"2018 WL 4922082","y":2018,"court":"U.S. Oct. 10","op":7,"by":{"1":"4-5, 36"}},{"t":"case","label":"Pet. Br., Demore v. Kim","cite":"2002 WL 31016560","y":2002,"court":"U.S. Aug. 29","by":{"1":"5"}},{"t":"case","label":"Pet. Br., Jennings v. Rodriguez","cite":"2016 WL 5404637","y":2016,"court":"U.S. Aug. 26","by":{"1":"5"}},{"t":"case","label":"Other Authorities (ctd.): Pet. Br., Nielsen v. Preap","cite":"2018 WL 2554770","y":2018,"court":"U.S. Jun. 1","op":4,"by":{"1":"4"}},{"t":"case","label":"Pet. Br., Reno v. Ma","cite":"2000 WL 1784982","y":2000,"court":"U.S. Nov. 24","by":{"1":"5, 36"}},{"t":"case","label":"Reply Br., Albence v. Guzman Chavez","cite":"2020 WL 3124376","y":2020,"court":"Mar. 14","by":{"1":"36"}},{"t":"case","label":"Allen v. Wright","cite":"468 U.S. 737","y":1984,"id":"1983/81-757","sc":1,"op":3,"sum":"The Court found that the circumstances involved in this case did not warrant federal-court adjudication.","sumSrc":"Oyez","by":{"2":"3"}},{"t":"case","label":"American Hosp. Ass’n v. Price","cite":"867 F.3d 160","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/867/160/","by":{"2":"13"}},{"t":"case","label":"Arizona v. Biden","cite":"40 F.4th 375","y":2022,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/40/375/","op":2,"by":{"2":"5, 9, 10"}},{"t":"case","label":"Finnbin, LLC v. CPSC","cite":"45 F.4th 127","y":2022,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/45/127/","by":{"2":"13"}},{"t":"case","label":"Garland v. Ming Dai","cite":"141 S. Ct. 1669","y":2021,"id":"2020/19-1155","sc":1,"sum":"The Ninth Circuit’s rule in immigration disputes—that in the absence of an explicit adverse credibility determination by an immigration judge or the Board of Immigration Appeals, a reviewing court must treat a petitioning noncitizen’s testimony as credible and true—cannot be reconciled with the terms of the Immigration and Nationality Act.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"18"}},{"t":"case","label":"NRDC, Inc. v. Callaway","cite":"392 F. Supp. 685","y":1975,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp./392/685/","by":{"2":"21"}},{"t":"case","label":"Professionals & Patients for Customized Care v. Shalala","cite":"56 F.3d 592","y":1995,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/56/592/","by":{"2":"15"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"22"}},{"t":"case","label":"Scripps-Howard Radio, Inc. v. FCC","cite":"316 U.S. 4","y":1942,"id":"scdb/1941-046","sc":1,"by":{"2":"17"}},{"t":"case","label":"The Wilderness Soc’y v. Norton","cite":"434 F.3d 584","y":2006,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/434/584/","sum":"Observing that “the agency’s top administrators clearly reserved for themselves unlimited discretion”.","sumSrc":"brief:2","by":{"2":"16"}},{"t":"case","label":"Winter v. NRDC, Inc.","cite":"555 U.S. 7","y":2008,"id":"2008/07-1239","sc":1,"sum":"The Court held that the standard for properly granting a preliminary injunction is not based on the \"possibility\" of irreparable harm to marine life, but rather that \"irreparable injury is likely\" in the absence of such an injunction.","sumSrc":"Oyez","by":{"2":"23"}},{"t":"usc","label":"5 U.S.C. § 705","url":"https://www.law.cornell.edu/uscode/text/5/705","stext":{"head":"§705. Relief pending review","paras":[[0,"When an agency finds that justice so requires, it may postpone the effective date of action taken by it, pending judicial review. On such conditions as may be required and to the extent necessary to prevent irreparable injury, the reviewing court, including the court to which a case may be taken on appeal from or on application for certiorari or other writ to a reviewing court, may issue all necessary and appropriate process to postpone the effective date of an agency action or to preserve status or rights pending conclusion of the review proceedings."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/705?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§705. Relief pending review","tname":"Government Organization and Employees","by":{"2":"17"}},{"t":"usc","label":"8 U.S.C. § 1225","url":"https://www.law.cornell.edu/uscode/text/8/1225","subs":["(b)(2)(A)"],"by":{"2":"13"}},{"t":"usc","label":"21 U.S.C. § 371","url":"https://www.law.cornell.edu/uscode/text/21/371","by":{"2":"19"}}]};